CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `sazka_pohled` AS select `a`.`sazka_id` AS `sazka_id`,`a`.`proplatil_bookmaker` AS `proplatil_bookmaker`,`a`.`proplacena` AS `proplacena`,`a`.`info` AS `info`,`a`.`betradar_sazka_id` AS `betradar_sazka_id`,`a`.`platna_od` AS `platna_od`,`a`.`platna_do` AS `platna_do`,`a`.`status` AS `status`,`a`.`live` AS `live`,`a`.`bookmaker_id` AS `bookmaker_id`,`a`.`vysledek` AS `vysledek`,`a`.`udalost_id` AS `udalost_id`,`a`.`typ_id` AS `typ_id`,`a`.`podtyp_id` AS `podtyp_id`,`a`.`overena` AS `overena`,`a`.`text` AS `text`,`a`.`ako` AS `ako`,`a`.`jednoducha` AS `jednoducha`,`a`.`risk_limit` AS `risk_limit`,`a`.`risk_limit_balance` AS `risk_limit_balance`,`b`.`poradi` AS `poradi`,`b`.`kurz` AS `kurz`,`b`.`kurz_zmena` AS `kurz_zmena`,`b`.`platny_od` AS `platny_od`,`c`.`nazev` AS `nazev`,`c`.`sloupec_id` AS `sloupec_id`,`c`.`poradi` AS `poradi_sloupec`,`a`.`betradar_autoupdate` AS `betradar_autoupdate`,`a`.`score` AS `score` from (`sazky` `a` join (`sazka_kurz` `b` join `podtyp_sloupce` `c` on((`b`.`sloupec_id` = `c`.`sloupec_id`))) on((`a`.`sazka_id` = `b`.`sazka_id`)));
